// One-shot helper: read the four generated logo PNGs and inject them as
// base64 constants into supabase/functions/seed-email-assets/index.ts,
// also extending the upload object-literal so the new files get pushed
// to the email-assets bucket on next invoke.
//
// Idempotent: if the AUTOGENERATED block is already present, it gets
// replaced. Existing LOGO_BLUE_B64 / LOGO_WHITE_B64 constants are
// preserved untouched (backward-compat for the preview tool).
//
// Usage:  node scripts/inject-seed-blobs.mjs

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.resolve(HERE, '..');

const SEED = path.join(REPO, 'supabase', 'functions', 'seed-email-assets', 'index.ts');
const ASSETS = path.join(REPO, 'public', 'assets', 'email');

const NEW_FILES = [
  { name: 'logo-on-white.png',     varName: 'LOGO_ON_WHITE_B64' },
  { name: 'logo-on-white@2x.png',  varName: 'LOGO_ON_WHITE_2X_B64' },
  { name: 'logo-on-dark.png',      varName: 'LOGO_ON_DARK_B64' },
  { name: 'logo-on-dark@2x.png',   varName: 'LOGO_ON_DARK_2X_B64' },
];

const BEGIN = '// ────── BEGIN AUTOGENERATED LOGO BASE64 ──────';
const END   = '// ────── END AUTOGENERATED LOGO BASE64 ──────';

function build() {
  const lines = [BEGIN];
  for (const f of NEW_FILES) {
    const buf = readFileSync(path.join(ASSETS, f.name));
    lines.push(`const ${f.varName} = "${buf.toString('base64')}";`);
  }
  lines.push(END);
  return lines.join('\n');
}

function main() {
  const block = build();
  let src = readFileSync(SEED, 'utf8');

  // 1. Inject (or replace) the autogenerated block right BEFORE Deno.serve.
  if (src.includes(BEGIN) && src.includes(END)) {
    src = src.replace(
      new RegExp(`${escapeRegex(BEGIN)}[\\s\\S]*?${escapeRegex(END)}`),
      block,
    );
    console.log('  · Replaced existing autogenerated block.');
  } else {
    const marker = 'Deno.serve(';
    const idx = src.indexOf(marker);
    if (idx < 0) throw new Error('Could not find Deno.serve in seed file.');
    src = src.slice(0, idx) + block + '\n\n' + src.slice(idx);
    console.log('  · Inserted new autogenerated block before Deno.serve.');
  }

  // 2. Extend the upload object literal to include the four new keys.
  const oldLiteral = `{ "logo-blue.png": LOGO_BLUE_B64, "logo-white.png": LOGO_WHITE_B64 }`;
  const newLiteral = `{
      "logo-blue.png":         LOGO_BLUE_B64,
      "logo-white.png":        LOGO_WHITE_B64,
      "logo-on-white.png":     LOGO_ON_WHITE_B64,
      "logo-on-white@2x.png":  LOGO_ON_WHITE_2X_B64,
      "logo-on-dark.png":      LOGO_ON_DARK_B64,
      "logo-on-dark@2x.png":   LOGO_ON_DARK_2X_B64,
    }`;
  if (src.includes(oldLiteral)) {
    src = src.replace(oldLiteral, newLiteral);
    console.log('  · Extended upload object literal with 4 new keys.');
  } else if (src.includes(`"logo-on-white.png":`)) {
    console.log('  · Upload object literal already extended (skipping).');
  } else {
    throw new Error('Could not find expected upload object literal to extend.');
  }

  writeFileSync(SEED, src, 'utf8');
  console.log('  ✓ seed-email-assets/index.ts updated.');
}

function escapeRegex(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

main();
